    private void gillsnoItemStateChanged(java.awt.event.ItemEvent evt) {//GEN-FIRST:event_gillsnoItemStateChanged
if (gillsno.isSelected()) {
    resultfield.setText("Cepe de Bordeaux");

    forestyes.setEnabled(false);
    forestno.setEnabled(false);
    ringyes.setEnabled(false);
    ringno.setEnabled(false);
    convexyes.setEnabled(false);
    convexno.setEnabled(false);
}        // TODO add your handling code here:
    }//GEN-LAST:event_gillsnoItemStateChanged

    private void gillsyesItemStateChanged(java.awt.event.ItemEvent evt) {//GEN-FIRST:event_gillsyesItemStateChanged
  if (gillsyes.isSelected()) {
    resultfield.setText("");

    forestyes.setEnabled(true);
    forestno.setEnabled(true);

    ringyes.setEnabled(false);
    ringno.setEnabled(false);

    convexyes.setEnabled(false);
    convexno.setEnabled(false);
}      // TODO add your handling code here:
    }//GEN-LAST:event_gillsyesItemStateChanged

    private void forestnoItemStateChanged(java.awt.event.ItemEvent evt) {//GEN-FIRST:event_forestnoItemStateChanged
   if (forestno.isSelected()) {
    resultfield.setText("");
    convexyes.setEnabled(true);
    convexno.setEnabled(true);
    ringyes.setEnabled(false);
    ringno.setEnabled(false);
}     // TODO add your handling code here:
    }//GEN-LAST:event_forestnoItemStateChanged

    private void forestyesItemStateChanged(java.awt.event.ItemEvent evt) {//GEN-FIRST:event_forestyesItemStateChanged
   if (forestyes.isSelected()) {
    resultfield.setText("");

    ringyes.setEnabled(true);
    ringno.setEnabled(true);

    convexyes.setEnabled(false);
    convexno.setEnabled(false);
}     // TODO add your handling code here:
    }//GEN-LAST:event_forestyesItemStateChanged

    private void ringyesItemStateChanged(java.awt.event.ItemEvent evt) {//GEN-FIRST:event_ringyesItemStateChanged
  if (ringyes.isSelected()) {
    resultfield.setText("Amanite Tue-Mouche");

    convexyes.setEnabled(false);
    convexno.setEnabled(false);
}      // TODO add your handling code here:
    }//GEN-LAST:event_ringyesItemStateChanged

    private void ringnoItemStateChanged(java.awt.event.ItemEvent evt) {//GEN-FIRST:event_ringnoItemStateChanged
if (ringno.isSelected()) {
    resultfield.setText("");

    convexyes.setEnabled(true);
    convexno.setEnabled(true);
}        // TODO add your handling code here:
    }//GEN-LAST:event_ringnoItemStateChanged

    private void convexyesItemStateChanged(java.awt.event.ItemEvent evt) {//GEN-FIRST:event_convexyesItemStateChanged
if (convexyes.isSelected()) {
    if (forestno.isSelected()) {
        resultfield.setText("Agaric Jaunissant");
    } else {
        resultfield.setText("Pied Bleu");
    }
}        // TODO add your handling code here:
    }//GEN-LAST:event_convexyesItemStateChanged

    private void convexnoItemStateChanged(java.awt.event.ItemEvent evt) {//GEN-FIRST:event_convexnoItemStateChanged
if (convexno.isSelected()) {
    if (forestno.isSelected()) {
        resultfield.setText("Coprin Chevelu");
    } else {
        resultfield.setText("Girolle");
    }
}        // TODO add your handling code here:
    }//GEN-LAST:event_convexnoItemStateChanged

    private void resetbtnActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_resetbtnActionPerformed
resultfield.setText("");

Gillsgrp.clearSelection();
Forestgrp.clearSelection();
Ringgrp.clearSelection();
Convexgrp.clearSelection();

gillsyes.setEnabled(true);
gillsno.setEnabled(true);

forestyes.setEnabled(false);
forestno.setEnabled(false);

ringyes.setEnabled(false);
ringno.setEnabled(false);

convexyes.setEnabled(false);
convexno.setEnabled(false);        // TODO add your handling code here:
    }//GEN-LAST:event_resetbtnActionPerformed

    private void exitbtnActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_exitbtnActionPerformed
WELCOME welcome = new WELCOME();
welcome.setVisible(true);
this.dispose();    // TODO add your handling code here:
    }//GEN-LAST:event_exitbtnActionPerformed

